import sys, os
sys.path.insert(0,'/tmp/rec')
from drive import run
from term import render

def cap(args, keys=(1.0,), rows=30, cols=100, settle=0.6, show=True, styles=False, exe='./executable', delay=0.05):
    raw = run([exe]+list(args), list(keys), rows=rows, cols=cols, settle=settle, delay=delay)
    t = render(raw, rows, cols)
    if show: print(t.text())
    if styles: print('--- styles ---'); print(t.dump_styles())
    return t, raw

